SELECT * FROM category_racers cr INNER JOIN racers r ON r.code=cr.racer_code INNER JOIN racer_results rr ON rr.id=cr.racer_result_id INNER JOIN entry_racers er ON rr.entry_racer_id=er.id INNER JOIN entry_categories ec ON ec.id=er.entry_category_id INNER JOIN entry_groups eg ON eg.id=ec.entry_group_id WHERE eg.meet_code=(SELECT eg2.meet_code FROM entry_categories e2 JOIN entry_groups eg2 ON eg2.id=e2.entry_group_id WHERE e2.id=24693) AND cr.reason_id=1 AND r.deleted=0 AND cr.deleted=0 AND rr.deleted=0 AND er.deleted=0 AND ec.deleted=0;
